fun observeLocation(): Flow<Location> = channelFlow {
    val listener = LocationListener { trySend(it) }
    awaitClose { locationManager.removeUpdates(listener) }
}

fun observeLessons(): Flow<List<Lesson>> = callbackFlow {
    val listener = firestore.collection("lessons").addSnapshotListener { snap, _ ->
        snap?.let { trySend(it.toObjects(Lesson::class.java)) }
    }
    awaitClose { listener.remove() }
}
